corrected_code:
router.get('/api/game/match/:matchSessionId/state', verifyGamerToken, async (req, res) => {
  const { matchSessionId } = req.params;

  const matchData = await redis.hgetall(`game_match:${matchSessionId}`);
  if (!matchData || !matchData.playerA) {
    return res.status(404).json({ error: 'Match session not active' });
  }

  const currentGamer = req.user.gamerTag;
  const spectators = JSON.parse(matchData.spectators || '[]');
  const isParticipant = matchData.playerA === currentGamer || matchData.playerB === currentGamer || spectators.includes(currentGamer);
  if (!isParticipant) {
    return res.status(403).json({ error: 'Forbidden: you are not a participant or spectator in this match' });
  }

  res.json({
    matchSessionId,
    playerA: matchData.playerA,
    playerB: matchData.playerB,
    boardState: JSON.parse(matchData.boardState || '{}'),
    spectators
  });
});
